files.lib/audit.sh:
source lib/nodes.sh
source lib/tls.sh
audit_nodes() {
    for_each_node "$NODE_LIST" audit_one_node
}
audit_one_node() {
    local host="$1"
    probe_tls_endpoint "$host" "$TLS_PORT"
}

files.lib/tls.sh:
probe_tls_endpoint() {
    openssl s_client -connect "$1:$2" -servername "$1" </dev/null
}
probe_plain_endpoint() {
    printf 'plain endpoint: %s:%s\n' "$1" "$2"
}
